#!/usr/bin/env python3
"""Exact Python replica of sim.c dynamics, for debugging gates.txt.
Usage: pysim.py <N> [--show]  (prints final result; --show dumps key signals per step)
"""
import sys

def parse(path="/app/gates.txt"):
    gates = {}
    deps = {}
    num_signals = 0
    with open(path) as f:
        for line in f:
            line = line.rstrip("\n")
            try:
                idx_s, op = line.split(" = ", 1)
                idx = int(idx_s[3:])
            except ValueError:
                continue
            num_signals = max(num_signals, idx + 1)
            if op in ("0", "1"):
                gates[idx] = ("c", int(op))
            elif op.startswith("~out"):
                gates[idx] = ("n", int(op[4:]))
                deps.setdefault(int(op[4:]), []).append(idx)
            elif op.startswith("out") and " " not in op:
                gates[idx] = ("c", None, int(op[3:]))  # copy
                deps.setdefault(int(op[3:]), []).append(idx)
            else:
                a, opch, b = op.split(" ")
                gates[idx] = (opch, int(a[3:]), int(b[3:]))
                deps.setdefault(int(a[3:]), []).append(idx)
                deps.setdefault(int(b[3:]), []).append(idx)
    return gates, deps, num_signals

def sim(N, show=False, steps=32000, gates=None, deps=None, ns=None):
    if gates is None:
        gates, deps, ns = parse()
    else:
        ns = ns if ns else 32
    import heapq
    values = [0] * (ns if ns else max(gates) + 1)
    n = len(values)
    for i in range(min(32, n)):
        values[i] = (N >> i) & 1
    update_queue = []
    next_queue = []
    next_in_queue = [0] * n
    step_number = -1

    def do_step():
        nonlocal update_queue, next_queue, next_in_queue
        if step_number > 0:
            update_queue, next_queue = next_queue, update_queue
            heapq.heapify(update_queue)
        next_queue = []
        next_in_queue = [0] * n
        did = [0] * n
        if step_number == 0:
            for i in range(n):
                heapq.heappush(update_queue, i)
        while update_queue:
            sig = heapq.heappop(update_queue)
            if did[sig]:
                continue
            did[sig] = 1
            if sig not in gates:
                continue
            g = gates[sig]
            old = values[sig]
            if g[0] == "c" and len(g) == 2:
                new = g[1]
            elif g[0] == "c":
                new = values[g[2]]
            elif g[0] == "n":
                new = 1 - values[g[1]]
            else:
                opch, x, y = g
                a, b = values[x], values[y]
                if opch == "&": new = a & b
                elif opch == "|": new = a | b
                elif opch == "^": new = a ^ b
                else: raise AssertionError
            if new != old:
                values[sig] = new
                for d in deps.get(sig, []):
                    if not did[d] and d > sig:
                        heapq.heappush(update_queue, d)
                    if not next_in_queue[d]:
                        heapq.heappush(next_queue, d)
                        next_in_queue[d] = 1

    for step in range(steps):
        step_number = step
        do_step()
        if show and (step < 40 or step % 200 == 0):
            print("step", step + 1, "values sample:", [values[i] for i in range(6)])
    # result
    res = 0
    for i in range(32):
        if values[ns - 32 + i]:
            res |= 1 << i
    return res, values

if __name__ == "__main__":
    N = int(sys.argv[1])
    show = "--show" in sys.argv
    res, values = sim(N, show=show)
    print("pysim result:", res)

