                deps.setdefault(int(op[4:]), []).append(idx)
            elif op.startswith("out") and " " not in op:
                gates[idx] = ("c", None, int(op[3:]))
                deps.setdefault(int(op[3:]), []).append(idx)
            else:
                a, opch, b = op.split(" ")
                gates[idx] = (opch, int(a[3:]), int(b[3:]))
                deps.setdefault(int(a[3:]), []).append(idx)
                deps.setdefault(int(b[3:]), []).append(idx)
    return gates, deps, ns

gates, deps, ns = parse()
SEQ0 = 6834          # first sequential signal (cmp0)
I0 = 6818            # first I bit
OUT0 = ns - 32       # first output signal

def eval_gate(sig, v):
    g = gates[sig]
    k = g[0]
    if k == "c" and len(g) == 2:
        return g[1]
    if k == "c":
        return v[g[2]]
    if k == "n":
        return 1 - v[g[1]]
    a, b = v[g[1]], v[g[2]]
    if k == "&": return a & b
    if k == "|": return a | b
    return a ^ b

def do_step(v, update_queue):
    """One settle step over signals SEQ0..ns-1 (isqrt block frozen)."""
    next_queue = []
    next_in = [0]*ns
    did = [0]*ns
    while update_queue:
        sig = heapq.heappop(update_queue)
        if did[sig]:
            continue
        did[sig] = 1
        new = eval_gate(sig, v)
        if new != v[sig]:
            v[sig] = new
            for d in deps.get(sig, ()): 
                if d < SEQ0:
                    continue  # isqrt side: frozen
                if not did[d] and d > sig:
                    heapq.heappush(update_queue, d)
                if not next_in[d]:
                    heapq.heappush(next_queue, d)
                    next_in[d] = 1
    return next_queue

def fib(k):
    a, b = 0, 1
    for _ in range(k):
        a, b = b, (a + b) & 0xFFFFFFFF
    return a

def run_seq(I, steps):
    v = [0]*ns
    for i in range(16):
        v[I0 + i] = (I >> i) & 1
    # step 0: all sequential signals queued (like sim.c step 0)
    update_queue = list(range(SEQ0, ns))
    heapq.heapify(update_queue)
    for _ in range(steps):
        update_queue = do_step(v, update_queue)
        if not update_queue:
            break
    out = 0
    for i in range(32):
        out |= v[OUT0 + i] << i
    return out

def main():
    Ilist = []
    Ilist += list(range(0, 4001))                      # full low range
    Ilist += [4000 + 131 * i for i in range(500)]     # stride through mid range
    Ilist += [65535 - 7 * i for i in range(60)]       # top range (long holds)
    Ilist += [65532, 65533, 65534, 65535]
    seen = set()
    Ilist = [x for x in Ilist if x not in seen and not seen.add(x)]
    t0 = time.time()
    bad = 0
    for j, I in enumerate(Ilist):
        steps = (I + 2) // 3 + 2   # ceil(I/3) + 2
        got = run_seq(I, steps)
        exp = fib(I)
        if got != exp:
            bad += 1
            if bad <= 15:
                print("FAIL I=%d got=%d exp=%d" % (I, got, exp), flush=True)
        if (j + 1) % 400 == 0:
            print("progress %d/%d bad=%d elapsed=%.0fs" % (j+1, len(Ilist), bad, time.time()-t0), flush=True)
    print("seq: %d I values, bad=%d, time=%.0fs" % (len(Ilist), bad, time.time()-t0), flush=True)
    sys.exit(1 if bad else 0)

main()
